import type { Record, TableName } from '../db'
import type { Role } from './Role'

/**
 * Maps the developer-facing `InterceptorAnswerType` union to the numeric codes ServiceNow
 * stores on `sys_wizard_answer.type`. Kept as a const object (not a TS enum) per repo convention.
 * Not exported — this only exists to derive `InterceptorAnswerType` below; a developer never
 * references this map directly. Keep in sync with ANSWER_TYPE_TO_CODE in
 * packages/build-plugins/src/interceptor-plugin.ts.
 */
const InterceptorAnswerTypeCodes = {
    answer: '1',
    leadingQuestion: '2',
    multipleChoice: '3',
    yesNo: '4',
    freeformText: '5',
    button: '6',
    externalChoice: '9',
} as const

/**
 * Controls which of `InterceptorAnswer`'s other fields are used:
 * - `'answer'` navigates to `targetUrl`.
 * - `'leadingQuestion'` advances to `nextQuestion`, another Interceptor question.
 * - `'multipleChoice'` presents choices from `sys_wizard_choice` records (created separately via
 *   the `Record` API). `sys_wizard_choice` has no coalesce key, so choices added on the instance
 *   outside Fluent must be reconciled by hand (new `Record()` call + `Now.del()` of the duplicate)
 *   — prefer `'externalChoice'` when the choices already exist as a `sys_choice` dropdown.
 * - `'button'` renders as a button labeled `buttonLabel`; the `answer` field is not displayed.
 * - `'externalChoice'` sources choices dynamically from `table`/`element`.
 * - `'yesNo'` / `'freeformText'` only use `payloadName` at runtime; other fields are stored but
 *   have no effect.
 */
export type InterceptorAnswerType = keyof typeof InterceptorAnswerTypeCodes

/**
 * One selectable option for an `Interceptor` question. May navigate to a URL, advance to another
 * question, render as a button, or source choices dynamically from a table — see `type` for
 * which fields apply. For `'multipleChoice'` answers, create `sys_wizard_choice` records
 * separately using the `Record` API.
 */
export type InterceptorAnswer = Now.Internal.WithID<{
    /**
     * Internal label for this answer. When omitted, the build plugin copies `answer` into the
     * generated `sys_wizard_answer.name` field, matching the platform form's UI behavior. Provide
     * an explicit value to override it.
     */
    name?: string
    /**
     * Text shown to the user for this option (labeled "User Prompt" on the platform form). Not
     * displayed when `type` is `'button'`; the visible button text comes from `buttonLabel`.
     */
    answer?: string
    /**
     * Controls which of this answer's other fields are used.
     * @default 'answer'
     */
    type?: InterceptorAnswerType | (string & {})
    /** Destination URL. Used when `type` is `'answer'`. */
    targetUrl?: string
    /**
     * Interceptor question to advance to. Used when `type` is `'leadingQuestion'`. Reference to
     * `sys_wizard`; accepts a raw sys_id string, a `Record<'sys_wizard'>`, or an `Interceptor(...)` expression
     */
    nextQuestion?: string | Record<'sys_wizard'> | Interceptor
    /** Visible text shown on the button. Used when `type` is `'button'`; the `answer` field is not displayed for buttons. */
    buttonLabel?: string
    /**
     * Table whose choice-list values (`sys_choice` rows) to source from. Used when `type` is
     * `'externalChoice'`. This pulls the dropdown options defined for `element` on this table —
     * it does NOT query records (rows) from the table itself. In a scoped app, the table must
     * be in the same scope as this definition (prefixed `<scope>_`); to target an out-of-box
     * table, use a global-scope app or a scoped table that extends it. Not validated against
     * real table existence at build time — an incorrect or renamed table name will not surface
     * as a build error. Query `sys_db_object` on the target instance to confirm the table exists
     * before authoring.
     */
    table?: TableName
    /**
     * Choice column on `table` whose `sys_choice` dropdown values populate the answer's options.
     * Used when `type` is `'externalChoice'`. The platform reads from `sys_choice` rows for this
     * column — it does not list records from the table. Like `table`, this is a plain string not
     * validated against the real column at build time. Query `sys_dictionary` (filtered by
     * `name=<table>^element=<element>`) on the target instance to confirm the column exists and
     * has a `dropdown` choice type before authoring.
     */
    element?: string
    /**
     * Optional value of the parent field when `element` is itself a dependent choice list on
     * `table` (for example, `subcategory` on `incident` depends on `category`). Used when `type`
     * is `'externalChoice'`; the platform uses this to filter which set of choices from
     * `element` should be shown. Omit for simple choice lists such as `state`.
     */
    dependentValue?: string
    /** Script executed when this answer is selected. Not gated to a specific `type`. */
    script?: string
    /**
     * Role names or `Role` objects allowed to see this answer at runtime. **Not enforced at
     * build time** — this is a runtime visibility filter, not a build-time access check. Note:
     * the underlying `roles` field itself is ACL- and dictionary-restricted to the `admin` role
     * for read and write on the platform's standard UI — Fluent can still set it at install time
     * via the generated XML (which bypasses UI-level ACLs), but a human editing the value
     * afterward through the platform form needs the `admin` role.
     */
    roles?: (string | Role)[]
    /**
     * Sort order among sibling answers under the same question — give each sibling a distinct
     * value or their display order becomes unpredictable.
     * @default 100
     */
    order?: number
    /** Whether this answer is presented to the user.
     * @default true
     */
    active?: boolean
    /**
     * Platform-internal payload correlation name. Exposed as-is since it is a plain developer-settable field.
     */
    payloadName?: string
}>

/**
 * Presents a question/decision panel before a user creates a new record on an intercepted table,
 * guiding them through a branching flow of `answers` to route the user to the right destination
 * form, URL, or follow-up question. For `'multipleChoice'` answers, create `sys_wizard_choice`
 * records separately using the `Record` API. This is the platform's "What type of X would you
 * like to create?" chooser mechanism, matched at runtime via `GlideappWizardIntercept` against
 * `intercepts`.
 *
 * Also accepts `protectionPolicy` (via `Now.Internal.WithIdAndMetadata`) to control edit/view
 * access for other developers after the application is installed.
 *
 * @interface
 */
export type Interceptor = Now.Internal.WithMetadata<{
    /**
     * Internal label for this question panel. Not shown to the end user. Identifies the record —
     * two Interceptors with the same `name` coalesce into a single record. Renaming an existing
     * Interceptor creates a new record on the instance and orphans the old one.
     */
    name: string
    /** Question text presented to the user. */
    question?: string
    /**
     * Previous question/panel in the flow. Reference to `sys_wizard`; accepts a raw sys_id
     * string, a `Record<'sys_wizard'>`, or an `Interceptor(...)` expression.
     */
    backPanel?: string | Record<'sys_wizard'> | Interceptor
    /**
     * Default next question/panel in the flow, used when the selected answer doesn't specify
     * its own `nextQuestion`. Reference to `sys_wizard`; accepts a raw sys_id string, a
     * `Record<'sys_wizard'>`, or an `Interceptor(...)` expression.
     */
    nextPanel?: string | Record<'sys_wizard'> | Interceptor
    /**
     * `*.do` page path this Interceptor triggers on instead of the table's default new-record
     * form, e.g. `'incident.do'`. The platform stores this as a plain string; in practice, every
     * out-of-box interceptor targets a single table.
     */
    intercepts?: string
    /** Answer options presented to the user for this question. */
    answers?: InterceptorAnswer[]
}>

/**
 * @param config - Configuration for the Interceptor
 */
export function Interceptor(config: Interceptor): Interceptor & Now.Internal.TableBrand<'sys_wizard'> {
    return config as Interceptor & Now.Internal.TableBrand<'sys_wizard'>
}
